import type { Task } from '../shared/types.ts'

/** Stranski ključ - npr. title, assignee, status, dueDate */
type SortKey = 'original' | 'title' | 'assignee' | 'status' | 'dueDate'

/** Smer razvrščanja */
type SortDirection = 'asc' | 'desc'

/** Izbrazena sekundarna smer za sekundarni ključ */
type SecondarySortDirection = 'asc' | 'desc'

interface PrimarySortConfig {
  key: SortKey
  direction: SortDirection
}

interface SecondarySortConfig {
  enabled: boolean
  key: SortKey | 'none'
  direction: SecondarySortDirection
}

/**
 * Normalizira niz za primerjavo: NFD, odstran. U+0300-U+036F (diakritika), male črke, UTF-16.
 */
function normalizeForComparison(value: string): string {
  if (typeof value !== 'string') return ''
  // NFD normalizacija (canonical decomposition)
  const nfd = value.normalize('NFD')
  // Odstrani diakritična besedila U+0300-U+036F
  const withoutDiactric = nfd.replace(/[\u0300-\u036F]/g, '')
  // Male črke (UTF-16)
  return withoutDiactric.toLocaleLowerCase('und')
}

/**
 * Primerjava dvou osnovnega ključa z normalizacijo za title/assignee
 */
function comparePrimaryValue(
  a: string | undefined, 
  b: string | undefined,
  key: 'title' | 'assignee'
): number {
  const normA = normalizeForComparison(a ?? '')
  const normB = normalizeForComparison(b ?? '')
  if (normA < normB) return -1
  if (normA > normB) return 1
  return 0
}

/**
 * Primerjava status ključa: todo < in_progress < done
 */
function compareStatus(a: string | undefined, b: string | undefined): number {
  const order: Record<string, number> = { todo: 0, in_progress: 1, done: 2 }
  const valA = a ?? ''
  const valB = b ?? ''
  const ordA = order[valA] ?? 3
  const ordB = order[valB] ?? 3
  if (ordA < ordB) return -1
  if (ordA > ordB) return 1
  return 0
}

